import json

def fix(s):
    if not isinstance(s, str):
        return s
    if not any(c in s for c in 'ãåæ'):
        return s
    try:
        return s.encode('latin1').decode('utf-8', errors='replace')
    except Exception:
        return s

with open('batches/batch_0022.json', encoding='utf-8') as f:
    data = json.load(f)

for item in data:
    for k in ['name','url','title','desc','body']:
        if k in item:
            item[k] = fix(item[k])

with open('batches/batch_0022_fixed.json', 'w', encoding='utf-8') as f:
    json.dump(data, f, ensure_ascii=False, indent=1)

print('done', len(data))
for i,item in enumerate(data):
    print(item['idx'], item['name'], '|', item['body'][:50].replace(chr(10),' '))
"
